from posectrl import *
from scipy.linalg import solve
class WrenchCtrl(PoseCtrl):
 def action(self,qdes,gain=20,damp=5,load=0,loadbody=12,loadpoint=None,comtarget=None):
  m,d,dk=self.m,self.d,self.dk;dk.qpos[:]=qdes;dk.qvel[:]=0;mujoco.mj_forward(m,dk)
  tau=dk.qfrc_bias.copy();Jp=np.zeros((3,m.nv));Jr=np.zeros((3,m.nv))
  if load:
   if loadpoint is None:loadpoint=dk.site_xpos[5]+[.035,0,.08]
   mujoco.mj_jac(m,dk,Jp,Jr,loadpoint,loadbody);tau+=Jp[2]*load*9.81
  Js=[]
  for si in [1,2]:
   mujoco.mj_jacSite(m,dk,Jp,Jr,si);Js.append(np.vstack([Jp,Jr]))
  J=np.vstack(Js);B=J[:,:6].T;fw=np.tile([1.,1.,1.,.0001,.01,.0001],2)
  f=fw*(B.T@solve((B*fw)@B.T+1e-9*np.eye(6),tau[:6],assume_a='sym'))
  tau-=J.T@f
  u=np.zeros(m.nu);u[:21]=qdes[self.qa]+tau[self.va]/self.kp[:21]
  for i in range(21,m.nu):
   if m.actuator_trntype[i]==0:u[i]=qdes[m.jnt_qposadr[m.actuator_trnid[i,0]]]
   else:
    tid=m.actuator_trnid[i,0];a=m.tendon_adr[tid];n=m.tendon_num[tid]
    u[i]=sum(qdes[m.jnt_qposadr[m.wrap_objid[j]]]*m.wrap_prm[j] for j in range(a,a+n))
  mujoco.mj_jacSubtreeCom(m,d,self.Jc,1);v=self.Jc@d.qvel
  if comtarget is None:comtarget=(self.mass*dk.subtree_com[1]+load*(loadpoint if loadpoint is not None else dk.site_xpos[5]))/(self.mass+load)
  com=(self.mass*d.subtree_com[1]+load*d.xpos[71])/(self.mass+load)
  u[[4,9]]+=gain*(com[0]-comtarget[0])+damp*v[0]
  u[[1,6]]+=2*(com[1]-comtarget[1])+.5*v[1]
  return np.clip(2*(u-self.lo)/(self.hi-self.lo)-1,-1,1)
if __name__=='__main__':
 s=Session('powerlift',instance='/app/instance.npz');m,d=s.model,s.data;c=WrenchCtrl(s)
