 d.qpos[:]=q;mujoco.mj_forward(m,d);q[2]+=.019-d.site_xpos[1,2];d.qpos[:]=q;mujoco.mj_forward(m,d)
 mi=m.geom_dataid[24];verts=m.mesh_vert[m.mesh_vertadr[mi]:m.mesh_vertadr[mi]+m.mesh_vertnum[mi]]@d.geom_xmat[24].reshape(3,3).T+d.geom_xpos[24];top=verts[np.argmax(verts[:,2])]
